package assessment

import (
	"encoding/json"
	"github.com/pzweuj/sepilens/internal/strictjson"
	"os"
	"testing"
)

// Generated by Octopus from a public MYH3 text report through its real Parquet
// reader and BuildPayload. It contains no patient text or provider credentials.
func TestOctopusSequenceWireContractPreservesCoordinatesAndValidates(t *testing.T) {
	b, err := os.ReadFile("testdata/octopus-ai-sequence-contract.json")
	if err != nil {
		t.Fatal(err)
	}
	var payloads map[string]json.RawMessage
	if err := json.Unmarshal(b, &payloads); err != nil {
		t.Fatal(err)
	}
	for _, feature := range []string{"acmg", "svcv4"} {
		t.Run(feature, func(t *testing.T) {
			var r Request
			if err := strictjson.Decode(payloads[feature], &r); err != nil {
				t.Fatal(err)
			}
			normalized, err := Normalize(r)
			if err != nil {
				t.Fatal("Octopus wire contract rejected", err)
			}
			if normalized.Variant.Pos != 10544634 || normalized.Variant.Assembly != "GRCh37" || normalized.Variant.Consequence != "missense_variant" || normalized.Variant.HGVSc != "c.2015G>A" {
				t.Fatal("sequence identity changed")
			}
			if len(normalized.Package.Sources) != 0 || len(normalized.Package.Criteria) != 0 {
				t.Fatal("input mapping fabricated medical evidence")
			}
			r.Variant.Pos = 0
			if _, err := Normalize(r); err == nil {
				t.Fatal("zero coordinate incorrectly accepted")
			}
		})
	}
}
